import {showCarbon} from './carbon-scenes.js?v=20261023-physicscomplete01';
import {useCases} from './carbon-models.js?v=20261023-physicscomplete01';
const $=s=>document.querySelector(s),button=(id,t)=>`<button id="${id}" class="secondary">${t}</button>`;
const select=(id,title,values,value='')=>`<label for="${id}" class="field-label">${title}</label><select class="lab-select" id="${id}"><option value="">Choose</option>${values.map(([v,t])=>`<option value="${v}" ${v===value?'selected':''}>${t}</option>`).join('')}</select>`;
export function mountCarbonWidget(l,p,root,{save,done,feedback}){
 const w=p.widget;w.passed??=[];const pass=msg=>{p.widgetDone=true;save();done();feedback(msg);};
 if(l.widget==='diamond-lab'){
 w.count??='';w.reason??='';w.current??='';root.innerHTML='<p>Rotate the network. The central gold carbon is the focus atom; boundary atoms have omitted neighbours. Count its bonds and connect the structure to properties.</p><label class="field-label" for="diamondCount">Covalent neighbours of the focus atom</label><input id="diamondCount" class="lab-input" type="number" min="0" max="8" value="'+w.count+'">'+select('diamondReason','Why is diamond hard?',[['network','Strong covalent bonds form a rigid 3D network'],['layers','Weakly attracted layers slide']],w.reason)+select('diamondCurrent','Why does it not conduct electricity?',[['noelectrons','There are no electrons in carbon'],['fixed','No delocalised electrons or mobile ions carry current']],w.current)+button('checkDiamond','Check the evidence');showCarbon('diamond');$('#diamondCount').oninput=e=>{w.count=e.target.value;save();};$('#diamondReason').onchange=e=>{w.reason=e.target.value;save();};$('#diamondCurrent').onchange=e=>{w.current=e.target.value;save();};$('#checkDiamond').onclick=()=>{if(w.count!==''&&Number(w.count)===4&&w.reason==='network'&&w.current==='fixed')pass('Correct: four covalent neighbours, a rigid network and no mobile charge carriers.');else feedback('Count the four connections at the focus carbon. Hardness comes from the rigid network; electrical insulation comes from a lack of mobile charge, not a lack of electrons.',true);};return;
 }
 if(l.widget==='graphite-lab'){
 w.slide??=0;w.force??='';w.carrier??='';w.melting??='';root.innerHTML='<p>Predict which interactions let graphite layers slide. Then displace the middle layer without breaking the bonds inside any sheet.</p>'+select('graphiteForce','What is overcome during sliding?',[['weak','Weak attractions between layers'],['covalent','All covalent bonds within sheets']],w.force)+button('checkGraphiteForce','Check the prediction')+`<label class="field-label" for="graphiteSlide">Middle-layer displacement: <span id="slideValue">${w.slide}</span></label><input id="graphiteSlide" type="range" min="0" max="100" value="${w.slide}">`+select('graphiteCarrier','What carries charge through the sheets?',[['electrons','Delocalised electrons'],['ions','Mobile carbon ions']],w.carrier)+select('graphiteMelting','Why does graphite still have a very high melting point?',[['strong','Strong covalent bonds within sheets need much energy to overcome'],['weak','There are only weak forces everywhere']],w.melting)+button('checkGraphite','Check the property explanations')+'<p class="micro-note">Displacement is symbolic, not a measurement of friction or force. The 2D view shows projected sheet fragments.</p>';showCarbon('graphite',w.slide);$('#graphiteForce').onchange=e=>{w.force=e.target.value;save();};$('#checkGraphiteForce').onclick=()=>{if(w.force==='weak'){if(!w.passed.includes('prediction'))w.passed.push('prediction');save();feedback('Correct: interlayer attractions are weak; the covalent sheets remain intact.');}else feedback('Separate within-sheet covalent bonds from weak attractions between sheets.',true);};$('#graphiteSlide').oninput=e=>{if(!w.passed.includes('prediction')){e.target.value=w.slide;feedback('Make the correct sliding prediction first.',true);return;}w.slide=Number(e.target.value);$('#slideValue').textContent=w.slide;if(w.slide>0&&!w.passed.includes('slide'))w.passed.push('slide');save();showCarbon('graphite',w.slide);};$('#graphiteCarrier').onchange=e=>{w.carrier=e.target.value;save();};$('#graphiteMelting').onchange=e=>{w.melting=e.target.value;save();};$('#checkGraphite').onclick=()=>{if(w.passed.includes('slide')&&w.carrier==='electrons'&&w.melting==='strong')pass('Correct: weakly attracted layers slide, delocalised electrons carry charge, and strong within-sheet bonds explain the high melting point.');else feedback('Predict and move the layer first. Then distinguish mobile electrons from ions and strong within-sheet bonds from weak interlayer attractions.',true);};return;
 }
 w.case??=0;w.answers??={};w.model??='graphene';const i=w.case,t=useCases[i];w.answers[i]??={material:'',evidence:''};const a=w.answers[i];root.innerHTML=select('carbonModel','Inspect a structure',[['graphene','Graphene · sheet'],['fullerene','C₆₀ · cage'],['nanotube','Nanotube · cylinder']],w.model)+`<p><b>Application ${i+1} / 3</b></p><p>${t.brief}</p>`+select('carbonMaterial','Choose the material',[['graphene','Graphene'],['nanotube','Carbon nanotubes'],['fullerene','Fullerene cage']],a.material)+select('carbonEvidence','Choose the supporting evidence',[['electrons','Single conducting sheet with delocalised electrons'],['strength','Strong long structures with low mass'],['hollow','Hollow molecular shape; release and toxicity still need tests']],a.evidence)+button('checkCarbonUse','Check material and evidence')+button('nextCarbonUse','Next application →')+`<p id="carbonUseProgress">${w.passed.length} / 3 justified choices</p><div class="callout">These are property-based examples, not proof that every carbon material suits every device or medical use. The tube is a shape sketch; the C₆₀ 3D model has all sixty atoms.</div>`;showCarbon(w.model);$('#carbonModel').onchange=e=>{w.model=e.target.value;save();showCarbon(w.model);};$('#carbonMaterial').onchange=e=>{a.material=e.target.value;save();};$('#carbonEvidence').onchange=e=>{a.evidence=e.target.value;save();};$('#checkCarbonUse').onclick=()=>{if(a.material===t.material&&a.evidence===t.evidence){if(!w.passed.includes(i))w.passed.push(i);save();$('#carbonUseProgress').textContent=w.passed.length+' / 3 justified choices';feedback(t.why);if(w.passed.length===3)pass('All three application choices justified. '+t.why);}else feedback('Match both the required shape and the useful property. A correct material with unrelated evidence is not a complete justification.',true);};$('#nextCarbonUse').onclick=()=>{w.case=(i+1)%3;save();mountCarbonWidget(l,p,root,{save,done,feedback});};
}
